  fr:{nav:{markets:'Actifs',guarantees:'Garanties'},markets:{title:'Actifs',sub:'Choisissez un actif et ouvrez son graphique en direct.'},hero:{secondary:'Voir les actifs'},common:{allMarkets:'Tous les actifs',refillDemo:'Recharger le solde démo',liveClients:'Transactions clients live'},wallet:{deposit:'Recharger le solde démo',refillText:'Si votre solde démo tombe à zéro, vous pouvez restaurer instantanément 1 000 $ pour continuer à vous entraîner.',demoTopup:'Recharger de 1 000 $'},trade:{refillZero:'Votre solde démo est épuisé. Rechargez-le avec 1 000 $ pour continuer.',openAfterRefill:'Recharger de 1 000 $'},pages:{guaranteesTitle:'Garanties',guaranteesBody:'Nous privilégions une structure claire, un accès rapide aux sections, des cotations en direct et une interface mobile soignée.'}},
  pt:{nav:{markets:'Ativos',guarantees:'Garantias'},markets:{title:'Ativos',sub:'Escolha um ativo e abra seu gráfico ao vivo.'},hero:{secondary:'Ver ativos'},common:{allMarkets:'Todos os ativos',refillDemo:'Repor saldo demo',liveClients:'Operações ao vivo de clientes'},wallet:{deposit:'Repor saldo demo',refillText:'Se o saldo demo chegar a zero, você pode restaurar instantaneamente US$ 1.000 para continuar praticando.',demoTopup:'Repor US$ 1.000'},trade:{refillZero:'Seu saldo demo acabou. Restaure US$ 1.000 para continuar operando.',openAfterRefill:'Repor US$ 1.000'},pages:{guaranteesTitle:'Garantias',guaranteesBody:'Priorizamos estrutura clara, acesso rápido às seções, cotações ao vivo e uma interface móvel refinada.'}},
